INSERT INTO `products` (`id`, `slug`, `name`, `category_id`, `description`, `active`, `created_at`, `image`, `imagewebp`, `imageswebp`, `price`, `code`, `lazer_type_id`, `meta_title`, `meta_keyword`, `meta_description`, `gender_type_id`, `colors`, `popular`, `new`, `to_order`, `is_absent`, `photo_updated_at`, `seo_title`, `seo_content`, `new_leather_color`, `new_leather_type`, `new_model`, `gtin`, `mpn`, `updated_at`, `order`, `size`, `hasThumbnail`, `imageOld`, `jpgDeleted`, `photosMoved`, `mainImage`, `reviewCount`, `rating`, `img_titles`, `reserv_price`) VALUES
(3493, 'folder-l-shk-kl', 'Чохол для ноутбука або планшета "Фолдер", розмір L', 226, '<p><strong>Чохол для ноутбука або планшета "Фолдер", розмір L</strong></p><p>• Розмір: 41.5*28 см., для комп"ютера 37 х 24 х 2 см<br>• Колір виробу: коньячний<br>• Вид шкіри: натуральна шкіра крейзі хорс з <a href="https://lavoks.com/tisnennya">тисненням</a> під крокодила<br>• Вид поверхні: матова поверхня з вінтажним ефектом<br>• Колір нитки : в колір шкіри<br>• Колір фурнітури: антік<br>• Кишені : на замовлення, позаду<br>• Застібка: на магніти</p><p data-sourcepos="25:1-25:113"><strong>Ексклюзивні чохли для ноутбуків та планшетів "Фолдер" від LAVOKS - надійність у кожній деталі!</strong></p><p data-sourcepos="27:1-27:277">Ці чохли не лише забезпечать надійний захист вашого пристрою від зовнішніх впливів, але й стануть яскравим акцентом вашого стилю.</p><p data-sourcepos="29:1-29:262">Якісна натуральна шкіра надає чохлам неповторного вигляду, підкреслюючи ваш бездоганний смак. Доступні у трьох основних розмірах (28х20 см, 35х25 см та 41.5х28 см), наші чохли ідеально підійдуть для широкого спектру ноутбуків та планшетів. Також є можливість зробити чохол за індивідуальними розмірами.&nbsp;</p><p data-sourcepos="31:1-31:186">Внутрішня частина чохлів виконана з штучного войлоку, що запобігає появі подряпин на вашому пристрої, пилу та захищає від легких ударів. Зручна застібка надійно фіксує чохол, забезпечуючи легкий доступ до вашого гаджета.</p>', 1, '2025-05-13 19:02:41', '["products\\/3493\\/chohli-dlya-noutbukiv-ta-planshetiv-folder-folder-l-sk-kl-54483.webp","products\\/3493\\/chohli-dlya-noutbukiv-ta-planshetiv-folder-folder-l-sk-kl-43067.webp","products\\/3493\\/chohli-dlya-noutbukiv-ta-planshetiv-folder-folder-l-sk-kl-21065.webp","products\\/3493\\/chohli-dlya-noutbukiv-ta-planshetiv-folder-folder-l-sk-kl-42849.webp","products\\/3493\\/chohli-dlya-noutbukiv-ta-planshetiv-folder-folder-l-sk-kl-40374.webp"]', '["products\\/3493\\/chohli-dlya-noutbukiv-ta-planshetiv-folder-folde