(3288, 'monro-sirm-n', 'Косметичка "Монро"', 128, '<p><strong>Косметичка &laquo;МОНРО&raquo;</strong></p>\n<ul>\n<li>Розмір: 20*10 см (косметичка пошита швами всередину)</li>\n<li>Колір виробу: бузковий металік</li>\n<li>Вид шкіри: натуральна&nbsp; шкіра &laquo;наппа&raquo;</li>\n</ul>\n<p>Косметичка Монро &ndash; багатофункціональний виріб. Має одне велике відділення та застібку на блискавку. Можна використовувати для косметики, як аптечку, або як тревел-портмоне (паспорт, гроші та інші документи). Також туди можна покласти окуляри або телефон.</p>', 1, '2024-10-22 18:44:57', '["products\\/3288\\/kosmetichki-monro_monro-sirm-n-15.webp","products\\/3288\\/kosmetichki-monro_monro-sirm-n-11.webp","products\\/3288\\/kosmetichki-monro_monro-sirm-n-11.webp"]', '["products\\/October2024\\/FQI511QQtPhUB1taG9ln.webp","products\\/October2024\\/HM27T5E5N7Zw3WYfG5MF.webp","products\\/October2024\\/qnhG3qzG01XPJ810FLLl.webp"]', '["products\\/3288\\/kosmetichki-monro_monro-sirm-n-15.webp","products\\/3288\\/kosmetichki-monro_monro-sirm-n-11.webp","products\\/3288\\/kosmetichki-monro_monro-sirm-n-11.webp"]', 420, 'Монро-СирМ-Н', 22, '', '', '', ',1,', ',83,', 1, 0, 0, 0, NULL, '', '', 0, 0, 0, '32888032105064', 'LA32888032105064VOKS', '2025-08-07 13:10:31', 7, '20*10 см (косметичка пошита швами всередину)', NULL, '["products\\/October2024\\/FQI511QQtPhUB1taG9ln.JPG","products\\/October2024\\/HM27T5E5N7Zw3WYfG5MF.JPG","products\\/October2024\\/qnhG3qzG01XPJ810FLLl.JPG"]', 1, 1, 'products/October2024/FQI511QQtPhUB1taG9ln-cropped.webp', NULL, NULL, NULL, 420),
(3287, 'monro-mm2-n', 'Косметичка "Монро"', 128, '<p><strong>Косметичка &laquo;МОНРО&raquo;</strong></p>\n<ul>\n<li>Розмір: 20*10 см (косметичка пошита швами всередину)</li>\n<li>Колір виробу: марсала металік</li>\n<li>Вид шкіри: натуральна&nbsp; шкіра &laquo;наппа&raquo;</li>\n</ul>\n<p>Косметичка Монро &ndash; багатофункціональний виріб. Має одне велике відділення та застібку на блискавку. Можна використовувати для косметики, як аптечку, або як тревел-портмоне (паспорт, гроші та інші документи). Також туди можна покласти окуляри або телефон.</p>', 1, '2024-10-22 18:42:41', '["products\\/3287\\/kosmetichki-monro_monro-mm2-n-10.webp","products\\/3287\\/kosmetichki-monro_monro-mm2-n-10.webp","products\\/3287\\/kosmetichki-monro_monro-mm2-n-13.webp"]', '["products\\/October2024\\/w7ZFrOVHxlVit7gTdacL.webp","products\\/October2024\\/vrfjEbGXbz6ynxCzqQS5.webp","products\\/October2024\\/IvaqxKip7UXvMUcKGWK5.webp"]', '["products\\/3287\\/kosmetichki-monro_monro-mm2-n-10.webp","products\\/3287\\/kosmetichki-monro_monro-mm2-n-10.webp","products\\/3287\\/kosmetichki-monro_monro-mm2-n-13.webp"]', 420, 'Монро-ММ2-Н', 22, '', '', '', ',1,', ',84,', 1, 0, 0, 0, NULL, '', '', 0, 0, 0, '32876774820799', 'LA32876774820799VOKS', '2025-08-07 13:10:31', 8, '20*10 см (косметичка пошита швами всередину)', NULL, '["products\\/October2024\\/w7ZFrOVHxlVit7gTdacL.JPG","products\\/October2024\\/vrfjEbGXbz6ynxCzqQS5.JPG","products\\/October2024\\/IvaqxKip7UXvMUcKGWK5.JPG"]', 1, 1, 'products/October2024/w7ZFrOVHxlVit7gTdacL-cropped.webp', NULL, NULL, NULL, 420),
