INSERT INTO `products` (`id`, `slug`, `name`, `category_id`, `description`, `active`, `created_at`, `image`, `imagewebp`, `imageswebp`, `price`, `code`, `lazer_type_id`, `meta_title`, `meta_keyword`, `meta_description`, `gender_type_id`, `colors`, `popular`, `new`, `to_order`, `is_absent`, `photo_updated_at`, `seo_title`, `seo_content`, `new_leather_color`, `new_leather_type`, `new_model`, `gtin`, `mpn`, `updated_at`, `order`, `size`, `hasThumbnail`, `imageOld`, `jpgDeleted`, `photosMoved`, `mainImage`, `reviewCount`, `rating`, `img_titles`, `reserv_price`) VALUES
(3237, 'richi-m-tkk', 'Рюкзак "Річі", розмір М', 198, '<p><strong>Рюкзак "Річі" , розмір М</strong><br />&bull; Розмір: 44*31*8 см.<br />&bull; Колір фурнітури : антік<br />&bull; Колір шкіри : темно-коричневий, матова поверхня з вінтажним ефектом<br />&bull; Назва шкіри : натуральна шкіра крейзі хорс&nbsp;</p>\n<div dir="auto">Рюкзак -велетень "РІЧІ" має багато кишень та відділення для ноутбука 15,6 дюймів.&nbsp;</div>\n<div dir="auto">Про кишені. Попереду 2 кишені на замочку. Позаду кишеня на замочку. Всередині є відділення для ноутбука. Також є 1 кишеня на замочку та 2 кишені звичайні. Без тканевої підкладки. Широкі лямки на плечі, довжина лямок регулюється. Кишені попереду, позаду, всередині - вистачить для всіх ваших речей. Можна пошити будь-якого кольору та з будь-якого типу шкіри. А ще можна обрати колір фурнітури (антік чи нікель). Можна зробити іменне <a href="https://lavoks.com/tisnennya">тиснення</a> латинськими або українськими літерами, добавити якись символ(герб, сердечко, квітоку, котика, собачку та інше, що можна знайти на нашому сайті в розділі "<a href="https://lavoks.com/tisnennya">тиснення</a>") або взагалі пошити різнокольоровим.&nbsp;</div>', 1, '2024-09-26 05:16:41', '["products\\/3237\\/ryukzaki-richi_richi-m-tkk-13.webp","products\\/3237\\/ryukzaki-richi_richi-m-tkk-12.webp","products\\/3237\\/ryukzaki-richi_richi-m-tkk-7.webp","products\\/3237\\/ryukzaki-richi_richi-m-tkk-11.webp","products\\/3237\\/ryukzaki-richi_richi-m-tkk-7.webp","products\\/3237\\/ryukzaki-richi_richi-m-tkk-15.webp","products\\/3237\\/ryukzaki-richi_richi-m-tkk-9.webp","products\\/3237\\/ryukzaki-richi_richi-m-tkk-11.webp","products\\/3237\\/ryukzaki-richi_richi-m-tkk-13.webp"]', '["products\\/September2024\\/x7VvnBcdGLa3rs7e3sWW.webp","products\\/September2024\\/A7Pa789btL9cfgwlqpIV.webp","products\\/September2024\\/oZmIuHVpSg4YpQXAKIJg.webp","products\\/September2024\\/VipTw9fflAd1ql5IxnKr.webp","products\\/September2024\\/XMN3iexZZ773HQva1Zq7.webp","products\\/Septe