(2562, 'veneciya-grande-tzhzh-f', 'Рюкзак "Венеція Гранде"', 61, '<p><strong>Рюкзак "Венеція Гранде"</strong>&nbsp;<br />&bull; Розмір: 36х26х12 см<br />&bull; Колір фурнитури : нікель<br />&bull; Колір шкіри: жовтий манго<br />&bull; Назва шкіри : натуральна шкіра флотар, рельєфна стійка поверхня "в зернятко",&nbsp; має невеликий природний глянець<br />Рюкзак великого розміру ( гарно вміщає формат А4) Попереду кишеня на замочку. Позаду звичайна кишенька. Всередині доволі глибока кишеня. Без підкладки.</p>', 1, '2023-01-23 05:29:07', '["products\\/2562\\/ryukzaki-veneciya-grande_veneciya-grande-tzhzh-f-7.webp","products\\/2562\\/ryukzaki-veneciya-grande_veneciya-grande-tzhzh-f-13.webp","products\\/2562\\/ryukzaki-veneciya-grande_veneciya-grande-tzhzh-f-14.webp","products\\/2562\\/ryukzaki-veneciya-grande_veneciya-grande-tzhzh-f-13.webp"]', '["products\\/January2023\\/p9bBXKQvuxU5kfmPLBVd.webp","products\\/January2023\\/urbvgYYTXvATe1UF3n0V.webp","products\\/January2023\\/rNCLNkByF77aufPoJbKU.webp","products\\/January2023\\/XeulKco5t9dvUPxfvLOc.webp"]', '["products\\/2562\\/ryukzaki-veneciya-grande_veneciya-grande-tzhzh-f-7.webp","products\\/2562\\/ryukzaki-veneciya-grande_veneciya-grande-tzhzh-f-13.webp","products\\/2562\\/ryukzaki-veneciya-grande_veneciya-grande-tzhzh-f-14.webp","products\\/2562\\/ryukzaki-veneciya-grande_veneciya-grande-tzhzh-f-13.webp"]', 2820, 'Венеция Гранде-ТЖЖ-Ф', 16, '', '', '', ',1,', ',75,', 1, NULL, 0, 0, NULL, '', '', 0, 0, 0, '25624401113688', 'LA25624401113688VOKS', '2025-08-07 13:08:06', 8, '36х26х12 см', NULL, '["products\\/January2023\\/p9bBXKQvuxU5kfmPLBVd.JPG","products\\/January2023\\/urbvgYYTXvATe1UF3n0V.JPG","products\\/January2023\\/rNCLNkByF77aufPoJbKU.JPG","products\\/January2023\\/XeulKco5t9dvUPxfvLOc.JPG"]', 1, 1, 'products/January2023/p9bBXKQvuxU5kfmPLBVd-cropped.webp', NULL, NULL, NULL, 2820),
(2561, 'amsterdam-chch-2', 'Рюкзак "Амстердам"', 62, '<p><strong>Рюкзак "Амстердам"&nbsp;</strong><br /><br />&bull; Розмір: 40*30*10 см<br />&bull; Колір фурнітури : антік<br />&bull; Колір шкіри :&nbsp; чорний<br />&bull; Назва шкіри : натуральна шкіра кайзер<br /><br />Рюкзак великого розміру (вільно входить формат А4) Спереду об''ємна кишеня на кнопках. Рюкзак закривається на блискавку, і зверху має кришку, яка закривається на кнопки -магніти. Усередині 2 кишені-перша закривається на блискавку, другий - досить глибокий і місткий. Без підкладки.</p>', 1, '2023-01-23 05:24:07', '["products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-13.webp","products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-7.webp","products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-9.webp","products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-13.webp","products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-13.webp","products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-5.webp"]', '["products\\/January2023\\/FrRQFjOohBaU8C1QL2Is.webp","products\\/January2023\\/PNPH9xmpJw6ALk750KOI.webp","products\\/January2023\\/qnAaDMN5X8C66v7HwXIy.webp","products\\/January2023\\/yQldzpgssFqSDqF47jsX.webp","products\\/January2023\\/NvXOyLUB5ev3y7wbEuDz.webp","products\\/January2023\\/0efeW3xxbKa2jirjj7tb.webp"]', '["products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-13.webp","products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-7.webp","products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-9.webp","products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-13.webp","products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-13.webp","products\\/2561\\/ryukzaki-amsterdam_amsterdam-chch-2-5.webp"]', 4180, 'Амстердам-ЧЧ-2', 4, '', '', '', ',3,2,', ',6,', 1, NULL, 0, 0, NULL, '', '', 0, 0, 0, '25619699617526', 'LA25619699617526VOKS', '2026-05-18 20:12:22', 9, '40*30*10 см', NULL, '["products\\/January2023\\/FrRQFjOohBaU8C1QL2Is.JPG","products\\/January2023\\/PNPH9xmpJw6ALk750KOI.JPG","products\\/January2023\\/qnAa