(2319, 'veneciya-grande-bb-2', 'Рюкзак "Венеція Гранде"', 61, '<p><strong>Рюкзак "Венеція Гранде"</strong><br /><br />&bull; Розмір: 36х26х12 см<br />&bull; Колір фурнитури : нікель<br />&bull; Колір шкіри: бежевий<br />&bull; Назва шкіри : натуральна шкіра кайзер<br /><br />Рюкзак великого розміру ( гарно вміщає формат А4) Попереду кишеня на замочку. Позаду звичайна кишенька. Всередині доволі глибока кишеня. Без підкладки.</p>', 1, '2022-06-01 04:12:42', '["products\\/2319\\/ryukzaki-veneciya-grande_veneciya-grande-bb-2-12.webp","products\\/2319\\/ryukzaki-veneciya-grande_veneciya-grande-bb-2-13.webp","products\\/2319\\/ryukzaki-veneciya-grande_veneciya-grande-bb-2-15.webp","products\\/2319\\/ryukzaki-veneciya-grande_veneciya-grande-bb-2-11.webp"]', '["products\\/June2022\\/0S6FYV5DA4NluOkoD4nb.webp","products\\/June2022\\/nsl7Quu7nuna0VfftQ7i.webp","products\\/June2022\\/3TxPmHL6HI1SpuT4eH74.webp","products\\/June2022\\/ZMGQyVBcNL1KJF42mNTe.webp"]', '["products\\/2319\\/ryukzaki-veneciya-grande_veneciya-grande-bb-2-12.webp","products\\/2319\\/ryukzaki-veneciya-grande_veneciya-grande-bb-2-13.webp","products\\/2319\\/ryukzaki-veneciya-grande_veneciya-grande-bb-2-15.webp","products\\/2319\\/ryukzaki-veneciya-grande_veneciya-grande-bb-2-11.webp"]', 2820, 'Венеция Гранде-ББ-2', 4, '', '', '', ',1,', ',18,', 0, NULL, 0, 0, NULL, '', '', 0, 0, 0, '23196397682536', 'LA23196397682536VOKS', '2025-08-07 13:07:03', 14, '36х26х12 см', NULL, '["products\\/June2022\\/0S6FYV5DA4NluOkoD4nb.JPG","products\\/June2022\\/nsl7Quu7nuna0VfftQ7i.JPG","products\\/June2022\\/3TxPmHL6HI1SpuT4eH74.JPG","products\\/June2022\\/ZMGQyVBcNL1KJF42mNTe.JPG"]', 1, 1, 'products/June2022/0S6FYV5DA4NluOkoD4nb-cropped.webp', NULL, NULL, NULL, 2820),
(2317, 'madrid-chch-2', 'Рюкзак "Мадрид"', 63, '<p><strong>Рюкзак "Мадрид"&nbsp;</strong></p>\n<ul>\n<li>&bull; Розмір: 31х26х11 см</li>\n<li>&bull; Колір фурнитури : нікель (жовта)</li>\n<li>&bull; Колір шкіри: чорний</li>\n<li>&bull; Назва шкіри : натуральна шкіра кайзер, стійка поверхня з невеликим глянцем</li>\n</ul>\n<p>Рюкзак середнього розміру, але доволі місткий. Закривається на блискавку. І зверху має кришку, яка закривається на магнітні кнопки. Ця кришка може бути як прикраса -іншого кольору або мати прикрашаючу строчку (квадратиками) Позаду звичайна кишенька на блискавці. Всередині доволі глибока кишеня. Без підкладки.</p>', 1, '2022-05-30 17:08:31', '["products\\/2317\\/ryukzaki-madrid_madrid-chch-2-9.webp","products\\/2317\\/ryukzaki-madrid_madrid-chch-2-6.webp","products\\/2317\\/ryukzaki-madrid_madrid-chch-2-15.webp","products\\/2317\\/ryukzaki-madrid_madrid-chch-2-15.webp","products\\/2317\\/ryukzaki-madrid_madrid-chch-2-6.webp"]', '["products\\/May2022\\/ktvPdcJkYTUCKFGmXitj.webp","products\\/May2022\\/77Co5N3qS1KwMphfKIij.webp","products\\/May2022\\/3ydcpIM1fRRBAxrUQT5r.webp","products\\/May2022\\/nmDJUDVcxOVtfjmKHJek.webp","products\\/May2022\\/uEbT11572mqSOjMapED9.webp"]', '["products\\/2317\\/ryukzaki-madrid_madrid-chch-2-9.webp","products\\/2317\\/ryukzaki-madrid_madrid-chch-2-6.webp","products\\/2317\\/ryukzaki-madrid_madrid-chch-2-15.webp","products\\/2317\\/ryukzaki-madrid_madrid-chch-2-15.webp","products\\/2317\\/ryukzaki-madrid_madrid-chch-2-6.webp"]', 3000, 'Мадрид-ЧЧ-2', 4, '', '', '', ',1,3,', ',6,', 1, NULL, 0, 0, NULL, '', '', 0, 0, 0, '23174246873217', 'LA23174246873217VOKS', '2025-08-07 13:07:03', 10, '31х26х11 см', NULL, '["products\\/May2022\\/ktvPdcJkYTUCKFGmXitj.JPG","products\\/May2022\\/77Co5N3qS1KwMphfKIij.JPG","products\\/May2022\\/3ydcpIM1fRRBAxrUQT5r.JPG","products\\/May2022\\/nmDJUDVcxOVtfjmKHJek.JPG","products\\/May2022\\/uEbT11572mqSOjMapED9.JPG"]', 1, 1, 'products/May2022/ktvPdcJkYTUCKFGmXitj-cropped.webp', NULL, NULL,